import{_ as e,o,c as a,a5 as r}from"./chunks/framework.BjM_ivYE.js";const n="/RBQ/images/app/settings-pwr.pc.en.png",g=JSON.parse('{"title":"Powering the external ports","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/interface/port-power.md","filePath":"manual/interface/port-power.md","lastUpdated":1790646309000}'),i={name:"manual/interface/port-power.md"};function s(d,t,l,h,c,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="powering-the-external-ports" tabindex="-1">Powering the external ports <a class="header-anchor" href="#powering-the-external-ports" aria-label="Permalink to &quot;Powering the external ports&quot;">​</a></h1><p>If a payload wired into an external port does nothing, the usual reason is that <strong>the port&#39;s power is off</strong>. Plugging the connector in does not energise the port — <strong>you switch it on in the app</strong>.</p><p>Wiring and pin assignments are in <a href="/RBQ/manual/interface/external-port.html">External ports</a>; the cables are listed under <a href="/RBQ/manual/product-descriptions/accessories.html#payload-cabling">Accessories</a>.</p><h2 id="where" tabindex="-1">Where to switch it on <a class="header-anchor" href="#where" aria-label="Permalink to &quot;Where to switch it on {#where}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Access</th><th>What lives there</th></tr></thead><tbody><tr><td><strong>Robot settings → Power</strong></td><td>Everyone</td><td>The auxiliary power you switch during everyday operation</td></tr><tr><td><strong>Maintenance → Power / System</strong></td><td><a href="/RBQ/manual/gui/developer-mode.html">developer mode</a> (level 2 or higher)</td><td>The above, plus rails that cut the connection or the robot&#39;s stance</td></tr></tbody></table><p>For an ordinary payload, <strong>Robot settings → Power</strong> is all you need.</p><p><img src="'+n+'" alt="Robot settings → Power"></p><h2 id="48v" tabindex="-1">Switching on a 48 V port <a class="header-anchor" href="#48v" aria-label="Permalink to &quot;Switching on a 48 V port {#48v}&quot;">​</a></h2><p>Ports that carry raw battery voltage — <code>POWER</code> (2-pin) and <code>PWR-CAN</code> (4-pin) — sit on the 48 V rails.</p><ol><li>Open <strong>Robot settings → Power</strong>.</li><li>Press <strong><code>Turn on</code></strong> on the <code>EXTERN (48V)</code> row — the power that goes out to the external expansion ports.</li><li>Confirm with <strong><code>Turn on</code></strong> in the <code>Turn this on?</code> dialog.</li><li>Check that the <strong>live voltage</strong> on that row comes up.</li></ol><p>If your add-on sits on <code>ARM · ADDON (48V)</code>, switch that row instead.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p><code>ARM · ADDON (48V)</code> is <strong>one PDU port shared</strong> by the arm and the add-on. Turning this rail off also cuts arm power, so make sure the arm is stopped before you switch it.</p></div></div><p>The 48 V rails put out <strong>raw battery voltage</strong>, which moves between 42.0 V and 58.4 V with the state of charge. Add your own converter if the payload needs a regulated supply.</p><h2 id="12v" tabindex="-1">Switching on a 12 V device <a class="header-anchor" href="#12v" aria-label="Permalink to &quot;Switching on a 12 V device {#12v}&quot;">​</a></h2><p>Devices that run on 12 V — cameras and lighting — have a per-device toggle; one tap switches it.</p><table tabindex="0"><thead><tr><th>Toggle</th><th>What it powers</th></tr></thead><tbody><tr><td><code>Speaker amp (12V)</code></td><td>Walkie-talkie audio output — silent while off</td></tr><tr><td><code>CCTV (12V)</code></td><td>The color camera of the PTZ unit</td></tr><tr><td><code>Thermal (12V)</code></td><td>The thermal camera of the PTZ unit</td></tr><tr><td><code>IR LED (12V)</code></td><td>Night illumination</td></tr></tbody></table><p><code>LiDAR (12V)</code>, <code>Cameras (5V)</code>, <code>Audio · USB hub (5V)</code>, <code>Vision PC (12V)</code> and <code>Comms (12V)</code> cut driving, video or the connection itself, so they live under <strong>Maintenance → Power / System</strong> (<a href="/RBQ/manual/gui/developer-mode.html">developer mode</a>).</p><h2 id="not-working" tabindex="-1">It is on but still does not work <a class="header-anchor" href="#not-working" aria-label="Permalink to &quot;It is on but still does not work {#not-working}&quot;">​</a></h2><ul><li><strong>The toggle is grayed out and will not press</strong> — the rail state has not arrived yet. Check the robot connection first (<a href="/RBQ/manual/gui/connection.html">Connection</a>).</li><li><strong>It does not flip immediately</strong> — the toggle shows the <strong>actual state</strong> the robot&#39;s PDU reports, and that takes about a second to come back.</li><li><strong>The voltage does not come up</strong> — check that the connector is seated and the cable is intact (<a href="/RBQ/manual/maintenance/connector.html">Connector handling</a>).</li><li><strong>Power is present but the device stays off</strong> — check you are within the per-port current limit: <code>POWER</code> 5 A, <code>PWR-CAN</code> 10 A, <code>12V/LAN</code> 2–3 A (<a href="/RBQ/manual/interface/external-port.html#user-port-pin-map">pin map</a>).</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us which port you wired what into, and the voltage shown on the power screen.</p><p><strong>→ <a href="/RBQ/manual/support/">Support</a></strong></p>',22)])])}const m=e(i,[["render",s]]);export{g as __pageData,m as default};
